#!/usr/bin/env node
// Generated by ajch_agent_framework 0.2.0. Edit the source named in .claude/kit.lock.json, then npm run kit.
/**
 * PostToolUse hook: after a Write/Edit, run the checks kit-config.json maps to
 * that path (for example content JSON -> content validators, docs/*.md ->
 * check-docs). On failure, exit 2 so Claude Code feeds the errors back to the
 * agent, which fixes the file before moving on. Other files pass through.
 *
 * Scripts resolve against the project first (repo layout: scripts/x.mjs), then
 * next to the hooks (packaged plugin layout: ../scripts/x.mjs). The project
 * checked is CLAUDE_PROJECT_DIR, passed as KIT_ROOT and <VERTICAL>_ROOT.
 */
import { spawnSync } from 'child_process';
import { existsSync, readFileSync } from 'fs';
import { join, dirname, basename } from 'path';
import { fileURLToPath } from 'url';

const here = dirname(fileURLToPath(import.meta.url));
let config = { checks: [] };
try { config = JSON.parse(readFileSync(join(here, 'kit-config.json'), 'utf-8')); } catch { process.exit(0); }
const project = process.env.CLAUDE_PROJECT_DIR || process.cwd();
const env = { ...process.env, KIT_ROOT: project };
if (config.vertical) env[`${config.vertical.toUpperCase()}_ROOT`] = project;

let input = '';
process.stdin.on('data', (c) => { input += c; });
process.stdin.on('end', () => {
  let path = '';
  try { path = (JSON.parse(input).tool_input?.file_path ?? '').replace(/\\/g, '/'); } catch { process.exit(0); }
  const scripts = [...new Set(config.checks.filter((c) => new RegExp(c.match).test(path)).flatMap((c) => c.run))];
  const out = [];
  for (const script of scripts) {
    const file = [join(project, script), join(here, '..', 'scripts', basename(script))].find(existsSync);
    if (!file) continue;
    const r = spawnSync(process.execPath, [file, '--quiet'], { encoding: 'utf-8', env });
    if (r.status !== 0) out.push((r.stderr || r.stdout).trim());
  }
  if (out.length) {
    process.stderr.write(`Checks failed after writing ${path}. Fix these before continuing:\n${out.join('\n')}\n`);
    process.exit(2);
  }
  process.exit(0);
});
